'use client';

const NOISE_BASE64 =
  'data:image/svg+xml;base64,';

export function FilmGrain() {
  return (
    <div
      className="tactile-grain-overlay pointer-events-none fixed inset-0 z-[9999] h-screen w-screen transform-gpu"
      style={{
        position: 'fixed',
        inset: 0,
        width: '100vw',
        height: '100vh',
        pointerEvents: 'none',
        zIndex: 9999,
        backgroundImage: `url("${NOISE_BASE64}")`,
        backgroundRepeat: 'repeat',
        backgroundSize: '160px 160px',
        transform: 'translateZ(0)',
      }}
      aria-hidden="true"
    />
  );
}
